function exerciseOverview(e,i){const count=e.sets.filter(s=>s.type!=='warmup').length,total=plannedSets(e);return `<article class="card exercise-summary" id="exercise-${i}"><button class="exercise-open" data-action="select:${i}" aria-expanded="false" aria-controls="exercise-entry"><span class="exercise-number">${String(workoutBlocks(state.active).findIndex(b=>b.members.includes(e.instanceId))+1).padStart(2,'0')}</span><span class="grow"><strong>${esc(e.name)}</strong><span class="subtitle">${realizedPlan(e)}</span></span><span class="exercise-state">${total&&count>=total?'✓':'＋'}</span></button></article>`}
function entryNumbers(e,weight,reps,prefix=''){return `<div class="entry"><div class="number-box"><label for="${prefix}weight">CHARGE · kg</label><input id="${prefix}weight" inputmode="decimal" value="${weight===''?'':fmt(weight)}" placeholder="—" aria-label="Charge en kg"><div class="row">${btn('−',prefix+'w:-1')}${btn('+',prefix+'w:1')}</div></div><div class="number-box"><label for="${prefix}reps">RÉPÉTITIONS</label><input id="${prefix}reps" inputmode="numeric" value="${reps}" aria-label="Répétitions"><div class="row">${btn('−',prefix+'r:-1')}${btn('+',prefix+'r:1')}</div></div></div><div class="row chips">${[6,7,8,9,10,12,15].map(r=>btn(r,prefix+'rep:'+r,reps===r?'selected':'')).join('')}</div>`}
function work(){if(!state.active){view='home';return home()}const s=state.active,e=ex();return `<div class="work-heading row between"><span class="eyebrow">${esc(s.name)}</span><div class="row">${btn('Terminer','finish','small')}<button class="small danger cancel-session" data-action="cancel-session" aria-label="Abandonner la séance">×</button></div></div><div class="session-exercises">${sessionExerciseMarkup(s,(item,i)=>i===selected?`<article class="card exercise-active" id="exercise-${selected}"><div id="exercise-entry"><div class="row between"><h2>${esc(e.name)}</h2><span class="rest" id="timer"></span></div>${proposalPanel(e)}${entryNumbers(e,weight,reps)}${compactFields()}${btn(editSet===null?'✓ Valider la série':'✓ Enregistrer la correction','validate','primary wide validate-btn')}${editSet!==null?btn('Annuler la correction','cancel-edit','wide'):''}<div class="row between entry-progress"><span class="subtitle">${realizedPlan(e)}</span>${!currentGroup()?btn('Suivant →','next','small'):''}</div><details class="entry-actions"><summary>Séries et options</summary>${planControl(e,'active',selected)}${e.alternative?btn('Choisir '+esc(e.alternative.name),'alternative','small'):''}${btn('Démarrer le repos','rest','small')}${e.sets.map((x,i)=>setRow(x,i,'current')).join('')}${!groupForExercise(s,e.instanceId)?btn('Grouper cet exercice','pair-current','small'):''}</details></div></article>`:exerciseOverview(item,i))}</div><details class="session-options"><summary>Adapter la séance</summary>${btn('Grouper des exercices','open-superset','small')}${btn('Modifier cette séance','adapt','small')}${modelId==='active'?editor(s,true):''}</details>`}
function compactFields(prefix='',set={}){return `<div hidden><input id="${prefix}type" value="${esc(set.type||'work')}"><input id="${prefix}rir" value="${set.rir??''}"><textarea id="${prefix}notes">${esc(set.notes||'')}</textarea><textarea id="${prefix}drops">${esc((set.drops||[]).map(x=>x.w+' × '+x.r).join('\n'))}</textarea></div>`}

