 const values=points.map(p=>p.value),lo=Math.min(...values),hi=Math.max(...values),pad=Math.max((hi-lo)*.15,Math.abs(hi)*.005,.1),min=Math.max(0,lo-pad),max=hi+pad;
 const stamp=d=>Date.parse(d+'T12:00:00Z'),start=stamp(points[0].date),end=stamp(points.at(-1).date),coord=p=>[55+(end===start?.5:(stamp(p.date)-start)/(end-start))*300,160-(p.value-min)/(max-min)*120];
