 return `<div class="eyebrow">VOTRE ÉVOLUTION, À VOTRE RYTHME</div><div class="row between"><h1>Corps.</h1><div class="row">${btn('Ajouter mon poids','body-weight','primary')}${btn('Ajouter des mensurations','body-add','small')}</div></div><p class="subtitle">Poids et mensurations restent sur cet appareil et dans votre sauvegarde JSON.</p>${bodyFormOpen?bodyEditor():''}<details class="body-latest" ${records.length?'open':''}><summary>Dernières mesures</summary><div class="body-latest-grid">${bodyFields.map(([id,label,unit])=>{const latest=records.findLast(m=>m.values[id]!==undefined);return latest?`<div><span>${label}</span><strong>${fmt(latest.values[id])} <small>${unit}</small></strong><small>${dayLabel(latest.date)}</small></div>`:''}).join('')||'<p class="muted">Votre premier relevé apparaîtra ici.</p>'}</div></details><label>Indicateur<select id="body-metric">${options(bodyFields.map(([id,label,unit])=>[id,`${label} · ${unit}`]),bodyMetric)}</select></label><label>Période<select id="body-period">${periodOptions(bodyPeriod)}</select></label><section class="card"><h2>${field[1]}</h2>${delta!==null?`<p class="body-delta">${delta>0?'+':''}${fmt(Number(delta.toFixed(2)))} ${field[2]} <span class="subtitle">entre le ${dayLabel(points[0].date)} et le ${dayLabel(points.at(-1).date)}</span></p>`:''}${trendChart(points,field[2],'body-edit')}${bodyMetric==='weight'?weightAveragePanel(records):''}<p class="subtitle">Touchez un point pour modifier le relevé. Seules les dates mesurées sont représentées.</p></section><div class="row between"><h2>Vos relevés</h2>${btn('Exporter les mesures CSV','body-csv','small')}</div>${[...points].reverse().map(p=>`<div class="measurement-row"><div><span class="subtitle">${dayLabel(p.date)}</span><strong>${fmt(p.value)} ${field[2]}</strong></div>${btn('Modifier','body-edit:'+encodeURIComponent(p.id),'small')}</div>`).join('')||'<p class="empty">Aucun relevé pour cet indicateur sur cette période.</p>'}`
